<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch} from 'vue';import * as THREE from 'three';const props=defineProps<{imageUrl?:string}>();const emit=defineEmits<{count:[number]}>();const canvas=ref<HTMLCanvasElement>();let cleanup=()=>{};
onMounted(()=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches){emit('count',0);return}let r:THREE.WebGLRenderer;try{r=new THREE.WebGLRenderer({canvas:canvas.value!,alpha:true,antialias:false})}catch{emit('count',0);return}const n=41000;r.setPixelRatio(Math.min(devicePixelRatio,1.5));const scene=new THREE.Scene(),cam=new THREE.PerspectiveCamera(45,innerWidth/innerHeight,.1,100);cam.position.z=12;const geo=new THREE.BufferGeometry(),data=new Float32Array(n*3),states=Array.from({length:3},()=>new Float32Array(n*3));for(let i=0;i<n;i++){const j=i*3,a=Math.random()*6.283,z=2*Math.random()-1,radius=Math.sqrt(1-z*z);states[0][j]=Math.cos(a)*radius*2.5;states[0][j+1]=Math.sin(a)*radius*3;states[0][j+2]=z*2;states[1][j]=(Math.random()-.5)*14;states[1][j+1]=(Math.random()-.5)*.12;states[1][j+2]=(Math.random()-.5)*2;states[2][j]=Math.cos(a)*radius*3;states[2][j+1]=Math.sin(a)*radius*3;states[2][j+2]=z*3;data.set(states[0].subarray(j,j+3),j)}let alive=true;function sample(url?:string){if(!url)return;let img=new Image();img.crossOrigin='anonymous';img.onload=()=>{if(!alive)return;let c=document.createElement('canvas');c.width=180;c.height=240;let x=c.getContext('2d')!;x.drawImage(img,0,0,c.width,c.height);let pixels:Uint8ClampedArray;try{pixels=x.getImageData(0,0,c.width,c.height).data}catch{return}for(let i=0;i<n;i++){let px=0,py=0,b=0;for(let k=0;k<20;k++){px=Math.floor(Math.random()*180);py=Math.floor(Math.random()*240);let j=(py*180+px)*4;b=(pixels[j]+pixels[j+1]+pixels[j+2])/765;if(Math.random()<b*b)break}let j=i*3;states[0][j]=(px/180-.5)*4.6;states[0][j+1]=(.5-py/240)*6;states[0][j+2]=b*.7}};img.src=url}sample(props.imageUrl);const stop=watch(()=>props.imageUrl,sample);geo.setAttribute('position',new THREE.BufferAttribute(data,3));const mat=new THREE.PointsMaterial({color:0xe4e4ff,size:.014,transparent:true,opacity:.65,depthWrite:false}),cloud=new THREE.Points(geo,mat);scene.add(cloud);function resize(){cam.aspect=innerWidth/innerHeight;cam.updateProjectionMatrix();r.setSize(innerWidth,innerHeight)}window.addEventListener('resize',resize);resize();let frame=0, lastVisible=true;function draw(){const hero=document.getElementById('hero'),work=document.getElementById('work'),contact=document.getElementById('contact');const y=window.scrollY;const begin=hero?.offsetTop||0,mid=work?.offsetTop||innerHeight,end=contact?.offsetTop||innerHeight*4;let segment=y<mid?0:1;let t=THREE.MathUtils.clamp((y-(segment?mid:begin))/Math.max(1,(segment?end:mid)-(segment?mid:begin)),0,1);t=t*t*(3-2*t);cloud.visible=innerWidth>=1024||y<innerHeight*.85;if(cloud.visible!==lastVisible){emit('count',cloud.visible?n:0);lastVisible=cloud.visible}for(let i=0;i<data.length;i++)data[i]=THREE.MathUtils.lerp(data[i],THREE.MathUtils.lerp(states[segment][i],states[segment+1][i],t),.055);geo.attributes.position.needsUpdate=true;cloud.rotation.y+=.0005;r.render(scene,cam);frame=requestAnimationFrame(draw)}emit('count',n);draw();cleanup=()=>{alive=false;stop();cancelAnimationFrame(frame);window.removeEventListener('resize',resize);geo.dispose();mat.dispose();r.dispose();emit('count',0)}});onUnmounted(()=>cleanup());
</script><template><canvas ref="canvas" class="fixed inset-0 w-full h-full pointer-events-none particle" aria-hidden="true"/></template>
